import math

def quote(state):
    t = state['t']
    best_bid = state['best_bid']
    best_ask = state['best_ask']
    bid_sizes = state['bid_sizes']
    ask_sizes = state['ask_sizes']
    inventory = state['inventory']
    max_inventory = state['max_inventory']
    max_order_size = state['max_order_size']
    memory = state['memory']

    # Calculate volume imbalance
    if bid_sizes[0] + ask_sizes[0] == 0:
        imbalance = 0
    else:
        imbalance = (bid_sizes[0] - ask_sizes[0]) / (bid_sizes[0] + ask_sizes[0])

    # Calculate weighted mid
    if bid_sizes[0] + ask_sizes[0] == 0:
        weighted_mid = best_bid + (best_ask - best_bid) / 2
    else:
        weighted_mid = (best_ask * bid_sizes[0] + best_bid * ask_sizes[0]) / (bid_sizes[0] + ask_sizes[0])

    # Determine bid and ask prices
    bid = max(best_bid - 2, math.floor(weighted_mid - 1))
    ask = min(best_ask + 2, math.ceil(weighted_mid + 1))

    # Determine bid size based on imbalance and inventory
    if imbalance > 0.5:
        bid_size = max_order_size
    else:
        bid_size = max(0, min(max_order_size, max_inventory - inventory))

    # Determine ask size based on imbalance and inventory
    if imbalance < -0.5:
        ask_size = max_order_size
    else:
        ask_size = max(0, min(max_order_size, max_inventory + inventory))

    # Ensure bid < ask and within best bid/ask
    if bid < ask and bid < best_ask and ask > best_bid:
        return {"bid": bid, "bid_size": bid_size, "ask": ask, "ask_size": ask_size}
    return {"bid": None, "bid_size": 0, "ask": None, "ask_size": 0}
